fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }

    let idx = get_idx(x, y);
    let voxel = grid_in[idx];
    let mat = get_material(voxel);
    let thermal = get_thermal(voxel);

    // === Fuel voxel burns ===
    let fuel_energy = ct(mat, 16u);

    if (fuel_energy > 0u) {
        let flash_point = ct(mat, 4u);
        // Fused condition check using bitwise AND
        if (thermal > flash_point && has_adjacent_air(x, y)) {
            let burns_into = ct(mat, 17u);
            let new_thermal = min(thermal + (fuel_energy >> 1u), 255u);
            grid_out[idx] = rewrite_voxel(voxel, burns_into, new_thermal, PHASE_BURNING);
            return;
        }
    }

    // === Air consumed by adjacent burning fuel ===
    if (mat == MAT_AIR) {
        // Vectorized bounds computation
        let bounds = vec4<u32>(u32(x > 0u), u32(x < GRID_WIDTH - 1u), u32(y > 0u), u32(y < GRID_HEIGHT - 1u));

        // Deterministic priority based on parity
        let parity = (x + y) & 1u;

        // Precompute neighbor data for valid directions
        var n_data = vec4<u32>(0u);
        if (bounds.x != 0u) { n_data.x = grid_in[get_idx(x - 1u, y)]; }
        if (bounds.y != 0u) { n_data.y = grid_in[get_idx(x + 1u, y)]; }
        if (bounds.z != 0u) { n_data.z = grid_in[get_idx(x, y - 1u)]; }
        if (bounds.w != 0u) { n_data.w = grid_in[get_idx(x, y + 1u)]; }

        // Extract materials in parallel
        let n_mats = n_data & vec4<u32>(MATERIAL_MASK);

        // Priority order based on parity
        let order = select(
            vec4<u32>(2u, 1u, 3u, 0u), // up, right, down, left
            vec4<u32>(0u, 2u, 1u, 3u), // left, up, right, down
            parity != 0u
        );

        for (var i = 0u; i < 4u; i++) {
            let dir = order[i];
            if (bounds[dir] == 0u || n_data[dir] == 0u) { continue; }

            let n_voxel = n_data[dir];
            let n_mat = n_mats[dir];
            let n_fuel = ct(n_mat, 16u);

            // Early continue if not fuel
            if (n_fuel == 0u) { continue; }

            let n_thermal = (n_voxel >> THERMAL_SHIFT) & THERMAL_MASK;
            let n_flash = ct(n_mat, 4u);

            // Fused burning check
            if (n_thermal > n_flash) {
                let smoke = ct(n_mat, 18u);
                if (smoke > 0u) {
                    let heat = n_fuel >> 1u;
                    let new_thermal = min(thermal + heat, 255u);
                    grid_out[idx] = rewrite_voxel(voxel, smoke, new_thermal, PHASE_GAS);
                    return;
                }
            }
        }
    }

    grid_out[idx] = voxel;
}

